class Solution {
  public int minRemoval(int[] nums, int k) {
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    int best = 1, left = 0;
    for (int right = 0; right < sorted.length; right++) {
      while ((long) sorted[left] * k < sorted[right]) left++;
      best = Math.max(best, right - left + 1);
    }
    return sorted.length - best;
  }
}
